+class DispatchPrologueRuntime final : public jit::LaunchRuntime<DispatchPrologueRuntime> {
+public:
+    struct Args {
+        // Templated arguments
+        int num_warps;
+        int num_ranks;
+        int num_max_tokens_per_rank;
+        int num_experts, num_topk;
+
+        // Parameters
+        topk_idx_t* topk_idx;
