+                            is_shared_phase ? &tensor_map_shared_l1_output :
+                                              &tensor_map_l1_output,
+                            smem_cd_l1_wg,
+                            out_n_idx,
+                            m_idx);
+                        cute::tma_store_arrive();
+                    }
