+                                            store_l2_scalar(
+                                                token_0 * WG_BLOCK_N +
+                                                    col_offset + r_0,
+                                                gate_pair.x);
+                                            store_l2_scalar(
+                                                token_0 * WG_BLOCK_N +
+                                                    col_offset + r_1,
+                                                up_pair.x);
+                                        }
+                                        if (token_1 < valid_m) {
+                                            store_l2_scalar(
+                                                token_1 * WG_BLOCK_N +
+                                                    col_offset + r_0,
+                                                gate_pair.y);
+                                            store_l2_scalar(
+                                                token_1 * WG_BLOCK_N +
+                                                    col_offset + r_1,
+                                                up_pair.y);
+                                        }
+                                    } else {
+                                        if (token_0 < valid_m) {
+                                            store_l2_scalar(
+                                                token_0 * WG_BLOCK_N +
+                                                    col_offset + r_0,
+                                                final_accum[
+                                                    accum_offset]);
+                                            store_l2_scalar(
+                                                token_0 * WG_BLOCK_N +
+                                                    col_offset + r_1,
+                                                final_accum[
+                                                    accum_offset + 2]);
+                                        }
+                                        if (token_1 < valid_m) {
+                                            store_l2_scalar(
+                                                token_1 * WG_BLOCK_N +
+                                                    col_offset + r_0,
+                                                final_accum[
+                                                    accum_offset + 1]);
+                                            store_l2_scalar(
+                                                token_1 * WG_BLOCK_N +
+                                                    col_offset + r_1,
+                                                final_accum[
+                                                    accum_offset + 3]);
