+
+        // ---------------- COMBINE ----------------
+        // NVLink barrier first: signals remote ranks that this rank's GEMM
+        // outputs (NVLink scatter targets) are fully written.
+        sm90_nvlink_barrier<kNumRanks, kNumSMs, kNumEpilogueThreads,
