+                        }
+                        return;
+                    }
+                    const uint32_t lane_in_half_warp = lane_idx % 16;
+                    const uint32_t row_in_decode_group = lane_in_half_warp / 2;
+                    const uint32_t packed_k_in_k32 = (lane_idx / 16) * 2 + lane_in_half_warp % 2;
