+
+struct Params {
+    uint32_t d_o;           // O head dimension
+    uint32_t input_gran;          // Scale granularity for input, must be 32
+    uint32_t wv_group_size; // Number of O heads per WV group. Always equal to 8 for V4 pro/flash
