+    int32_t* __restrict__ scale_factors;    // [n_wv_group, d_proj_out, wv_group_size*d_o/gran/4], contiguous on the SECOND dim (DeepGeMM's format)
+    uint64_t stride_scale_factors_dim0, stride_scale_factors_dim2;
+
+    // Output tensors
