+
+def quantize_to_e2m1_codes(x: torch.Tensor) -> torch.Tensor:
+    """Round to the nearest e2m1 value with the semantics of
+    ``cvt.rn.satfinite.e2m1x2.f32`` (ties to even, saturating to +-6) and return
