+    scale = cast_scale_inv_to_ue8m0(x.abs().amax(dim=-1) / 448.0)
+    data = (x / scale.unsqueeze(-1)).to(torch.float8_e4m3fn).view(torch.uint8)
+    scale_u8 = scale.to(torch.float8_e8m0fnu).view(torch.uint8)
